import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { sumDue, useRates } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { useCap, useFloor, useLate } from '../access/access';
import { useAsOf } from '../sheet/asof.slot';
import { GRADES } from '../people/people';
import { STATUSES, sheetFigures, useDescendantFigures } from './consolidated';

// The consolidated figures, over the sheet and all its descendants: everyone on them, and each
// sheet's due-total and overdue-total as that sheet shows them, added up. The sheet's own figures
// are the header's; with no children these are just those. Per grade, the due-totals of the people
// on it (retired people left out), and per status the count of claims in it, added up over the tree. While the screen shows an as-of date,
// every sheet of the tree is shown as it stood at the end of that date, with that date as its today.
function Consolidated({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const [asOf] = useAsOf();
  const descendants = useDescendantFigures(sheetId, asOf).data ?? [];

  const own = sheetFigures(people, claims, rates, today, floor, late, cap);
  const all = [own, ...descendants];
  const count = all.reduce((n, f) => n + f.people, 0);

  return (
    <section data-testid="consolidated">
      Consolidated — People: <strong data-testid="consolidated-people-count">{count}</strong>{' '}
      Due: <strong data-testid="consolidated-due-total">{sumDue(all.map((f) => f.dueTotal))}</strong>{' '}
      Overdue: <strong data-testid="consolidated-overdue-total">{sumDue(all.map((f) => f.overdueTotal))}</strong>
      <table>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>Grade {g}</td>
              <td data-testid={`consolidated-grade-${g}-due-total`}>{sumDue(all.map((f) => f.gradeDueTotals[g]))}</td>
            </tr>
          ))}
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`consolidated-status-${s}-count`}>{all.reduce((n, f) => n + f.statusCounts[s], 0)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -99.5, Component: Consolidated });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Claim, ClaimStatus } from '../claims/claims';
import { GRADES, liveHolds } from '../people/people';
import type { Grade, Person } from '../people/people';
import { personDueTotal, sumDue, trimmedSumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';
import { personOverdue } from '../overdue/overdue';
import { floorOf, lateOf } from '../access/access';
import type { Settings } from '../access/access';
import type { Sheet } from '../sheet/sheet';

/** Every status the consolidated figures count. */
export const STATUSES: ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'];

/**
 * A sheet's own figures, as its header shows them: its people, its due-total and its overdue-total;
 * and, as its summary shows them, per grade the due-totals of the people on it (retired people left
 * out) added up, and per status how many claims have it.
 */
export type Figures = {
  people: number;
  dueTotal: string;
  overdueTotal: string;
  gradeDueTotals: Record<Grade, string>;
  statusCounts: Record<string, number>;
};

/** A sheet's figures from what it holds — the one working the header and the consolidated figures share. */
export function sheetFigures(
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  today: string,
  floor: Dated,
  late: Late,
  cap: string,
): Figures {
  const claimsOf = (id: string) => claims.filter((c) => c.personId === id);
  const dueOf = (p: Person) => personDueTotal(rates, p.grades, today, claimsOf(p.id), liveHolds(p, today), floor, late, cap);
  const active = people.filter((p) => !p.retired);
  return {
    gradeDueTotals: Object.fromEntries(
      GRADES.map((g) => [g, sumDue(active.filter((p) => p.grade === g).map(dueOf))]),
    ) as Record<Grade, string>,
    statusCounts: Object.fromEntries(STATUSES.map((s) => [s, claims.filter((c) => c.status === s).length])),
    people: people.length,
    dueTotal: trimmedSumDue(
      people.map(dueOf),
    ),
    overdueTotal: trimmedSumDue(
      people.map((p) => personOverdue(rates, p.grades, today, claimsOf(p.id), liveHolds(p, today), floor, late).total),
    ),
  };
}

const enc = encodeURIComponent;

/**
 * A sheet's figures, every part of it read fresh from the store: as it is now, or, while the screen
 * shows an as-of date, as it stood at the end of that date (each read names it, and the sheet read
 * answers with that date as its today).
 */
async function readFigures(sheetId: string): Promise<Figures> {
  const [sheet, people, claims, rates, settings] = await Promise.all([
    getJson<Sheet>(`/api/sheets/${enc(sheetId)}`),
    getJson<{ people: Person[] }>(`/api/sheets/${enc(sheetId)}/people`).then((r) => r.people),
    getJson<{ claims: Claim[] }>(`/api/sheets/${enc(sheetId)}/claims`).then((r) => r.claims),
    getJson<{ rates: Rate[] }>(`/api/sheets/${enc(sheetId)}/rates`).then((r) => r.rates),
    getJson<Settings>(`/api/sheets/${enc(sheetId)}/settings`),
  ]);
  return sheetFigures(people, claims, rates, sheet.today, floorOf(settings), lateOf(settings, sheet.today), settings.cap ?? '');
}

/**
 * The figures of each of the sheet's descendants: the sheets naming it as their parent, theirs, and
 * so on, each as the screen's as-of date shows it (as it is now while none is set). Kept under the
 * sheet's own key with the as-of date, so loading the sheet again, or changing the date, re-reads them all.
 */
export function useDescendantFigures(sheetId: string, asOf: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'descendants', asOf] as const,
    queryFn: async () => {
      const { descendants } = await getJson<{ descendants: string[] }>(`/api/sheets/${enc(sheetId)}/descendants`);
      return Promise.all(descendants.map(readFigures));
    },
  });
}
